def _fit(x,y):
    return np.linalg.lstsq(x,y,rcond=1e-10)[0]


def _coordinates(study,x):
    a=study['panel_a']; u=np.asarray(a['u']); v=np.asarray(a['v'])
    i,j=np.triu_indices(len(u),1)
    du=u[i]-u[j]; dv=v[i]-v[j]
