            resid = target-g@coef
            lever = np.einsum('ij,ji->i', g, solve(cov, g.T, assume_a='pos')) + 1/n
            loo = np.mean(np.abs(resid)/np.maximum(1-lever, .05))
            score = loo*(1+.012*dof)
            old = models.get(tuple(ix))
